 for(const row of [['진행',reach(a),reach(b)],['최종 DPS',fmt(a.actual),fmt(b.actual)],['잔여 목숨',a.progression?.livesLeft??'—',b.progression?.livesLeft??'—'],['일반몹 이탈',a.lineSafety?.leaks??'—',b.lineSafety?.leaks??'—']]){const tr=document.createElement('tr');for(const text of row){const td=document.createElement('td');td.textContent=text;tr.append(td);}table.append(tr);}box.append(table);
 const note=document.createElement('small');note.textContent='시작 후보는 선택한 편성으로 생성한 첫 계산 배치입니다. 실제 전장 적용 전 비교입니다.';box.append(note);
 for(const [label,data]of [['시작 후보 맵 보기',composeInitial],['현재 최고 맵 보기',composeBest]]){const button=document.createElement('button');button.textContent=label;button.onclick=()=>renderCompositionLive(data,team,!composeWorker,label.replace(' 맵 보기',''));box.append(button);}
