let pendingSettingChange=null;
function previewSettingChange(next,title){const rows=CoopConvenience.diff(state,next);pendingSettingChange={next,fingerprint:JSON.stringify(state),title,returnTo:document.querySelector('.settings-dialog[open]')?.id};$('#setting-preview-summary').textContent=title+' · '+rows.length+'개 값 변경 · 적용 전에는 현재 설정을 유지합니다.';$('#setting-preview-status').textContent='';const table=document.createElement('table'),head=document.createElement('tr');for(const text of ['대상 · 항목','현재','변경 후']){const th=document.createElement('th');th.textContent=text;head.append(th);}table.append(head);const labels={you:'내 진영',partner:'파트너',perDemon:'초마신',level:'레벨',lib:'해방',skinLevels:'스킨 추가 레벨',relicLevel:'전용 유물',traits:'특성',relics:'공통 유물',codexSS:'SS 도감',codexSSS:'SSS 도감',eggbyLevel:'에그비 레벨',eggbyLib:'에그비 해방',eggbySkinLevels:'에그비 스킨',magicStones:'보유 마석'};for(const row of rows){const tr=document.createElement('tr');for(const value of [row.path.map(key=>labels[key]||(D.DEMON_BY_SLUG.has(key)?name(key):key)).join(' · '),row.before,row.after]){const td=document.createElement('td');td.textContent=value===undefined?'미설정':typeof value==='object'?JSON.stringify(value):String(value);tr.append(td);}table.append(tr);}$('#setting-preview-table').replaceChildren(table);$('#setting-preview-apply').disabled=!rows.length;openSettings('setting-preview-dialog');}
$('#setting-preview-apply').onclick=()=>{const pending=pendingSettingChange;if(!pending)return;if(pending.fingerprint!==JSON.stringify(state)){$('#setting-preview-status').textContent='현재 설정이 변경되었습니다. 미리보기를 다시 열어 주세요.';return;}snapshot();state=pending.next;pendingSettingChange=null;result=null;$('#setting-preview-dialog').close();refresh();renderTraits();queue();$('#shortcut-status').textContent='✓ '+pending.title+' 적용 완료 · 되돌리기 가능';if(pending.returnTo)openSettings(pending.returnTo);};

function compositionStatus(){if(!composeWorker)return;const elapsed=performance.now()-composeStarted,p=composeLast;$('#compose-status').textContent=(p?.evaluated||0)+'개 검토 · 실제 계산 '+Math.max(0,(p?.evaluated||0)-composePriorCount-(p?.hits||0))+' / 캐시 '+(p?.hits||0)+' · 시간·횟수 제한 없음 · 경과 '+Math.floor(elapsed/1000)+'초'+(p?' · 현재 최고 '+fmt(p.best)+' · 중지하면 최고 결과를 적용할 수 있습니다.':' · 첫 배치 계산 중')+(composeUpdated?' · 최고 갱신 '+Math.max(0,Math.floor((performance.now()-composeUpdated)/1000))+'초 전':'');$('#compose-progress').removeAttribute?.('value');}
