$('#open-compose').onclick=()=>{if(composeWorker||composeProposal){openSettings('composition-dialog');return;}if(!Object.values(composeCounts).some(n=>n>0))loadComposition();else renderCompositionRoster();openSettings('composition-dialog');};$('#compose-load').onclick=loadComposition;$('#compose-side').onchange=()=>loadComposition();$('#compose-edit').onclick=()=>{invalidateComposition();$('#compose-setup').hidden=false;renderCompositionLocks();};for(const id of ['compose-boost','compose-depth','compose-omen-growth','compose-mirror'])$('#'+id).onchange=()=>{invalidateComposition();renderCompositionLocks();};$('#compose-cancel').onclick=()=>{if(composeLast?.checkpoint)finishComposition({...composeLast.checkpoint,stopped:true,elapsed:performance.now()-composeStarted},$('#compose-side').value,true);else{invalidateComposition();$('#compose-status').textContent='첫 후보 완료 전에 중지했습니다. 기존 배치는 유지됩니다.';}};
