function startComposition(resume=false){const saved=resume?composeResume:null;if(resume&&(!saved||saved.fingerprint!==JSON.stringify(state))){$('#compose-status').textContent='설정이 변경되어 새로 계산해야 합니다.';return;}invalidateComposition();if(saved)composeInitial=saved.initial;renderCompositionLive.stackBaseline=null;const entries=Object.entries(composeCounts).filter(([,count])=>count>0).map(([slug,count])=>({slug,count})),composeSide=$('#compose-side').value,boostCount=Number($('#compose-boost').value);try{CoopOptimize.composition(state,entries,composeSide,boostCount,E,D,G);}catch(e){$('#compose-status').textContent=e.message;return;}composeFingerprint=JSON.stringify(state);const payload={...structuredClone(state),id:Date.now(),kind:'compose',entries,composeSide,boostCount,composeMirror:$('#compose-mirror').checked,...compositionLocks(),omenGrowth:$('#compose-omen-growth').checked,depth:$('#compose-depth').value};if(saved){payload.resumeLayout={cells:saved.checkpoint.cells,marks:saved.checkpoint.marks};composePriorCount=saved.checkpoint.evaluated||0;}else composePriorCount=0;payload.searchSeed=(Date.now()>>>0)||12345;composePayload=structuredClone(payload);const active=composeWorker=new Worker(workerUrl);$('#compose-setup').hidden=true;$('#compose-edit').hidden=true;$('#compose-live').hidden=false;$('#compose-live').textContent='첫 추천 배치를 계산하고 있습니다…';composeStarted=performance.now();composeUpdated=0;composeLast=null;composeDeadline=Infinity;$('#compose-start').disabled=true;$('#compose-cancel').hidden=false;$('#compose-progress').hidden=false;composeTick=setInterval(compositionStatus,500);compositionStatus();active.onmessage=({data})=>{if(composeWorker!==active)return;if(data.error){stopComposition('추천 실패: '+data.error);return;}if(data.kind==='compose-progress'){data.evaluated+=composePriorCount;if(data.checkpoint)data.checkpoint.evaluated=data.evaluated;const changed=!composeLast||(data.checkpoint?.result&&composeLast.checkpoint?.result?CoopOptimize.compare(data.checkpoint.result,composeLast.checkpoint.result)>0:data.best>composeLast.best);composeLast=data;if(typeof window!=='undefined')saveCompositionRecovery();if(changed&&data.checkpoint){if(!composeInitial)composeInitial=structuredClone(data.checkpoint);composeReason=CoopConvenience.reason(composeBest?.result,data.checkpoint.result);composeUpdated=performance.now();composeBest=data.checkpoint;if(typeof window!=='undefined')saveCompositionRecovery();renderCompositionLive(data.checkpoint,composeSide);renderCompositionComparison(composeSide);}compositionStatus();return;}if(data.kind==='composed'){data.evaluated+=composePriorCount;finishComposition(data,composeSide);}};active.onerror=e=>stopComposition('추천 오류: '+e.message);active.postMessage(payload);};
$('#compose-apply').onclick=()=>{if(!composeProposal)return;if(JSON.stringify(state)!==composeFingerprint){invalidateComposition();$('#compose-status').textContent='배치·세팅이 변경되었습니다. 다시 계산하세요.';return;}const proposal=composeProposal;optimizationBackup=structuredClone(state);try{localStorage.setItem('stack-lab-before-optimization-v1',JSON.stringify(optimizationBackup));}catch{}snapshot();state.cells=structuredClone(proposal.cells);state.marks=structuredClone(proposal.marks);state.omenGrowth=!!proposal.result.omenAuto;state.fullProgress=!!proposal.result.progression;state.stackFromWaveOne=!!proposal.result.stackFromWaveOne;if(proposal.result.evaluationTarget)state.target=proposal.result.evaluationTarget;targets();selected=null;refresh();queue();$('#compose-status').textContent='추천배치를 적용했습니다. 되돌리기 또는 자동 배치 전 복원으로 유닛·장판을 복원할 수 있습니다.';};
