$('#calculation-mode').onchange=()=>{calculationMode=$('#calculation-mode').value;$('#calculate-now-main').hidden=calculationMode!=='manual';try{localStorage.setItem('stack-lab-calculation-mode',calculationMode);}catch{}queue();};
